CDgnUnicodeTextWidth::CDgnUnicodeTextWidth()
{
	m_mData.RemoveAll();
	BuildDataMap();
	BuildTextData();
}

CDgnUnicodeTextWidth::~CDgnUnicodeTextWidth()
{
}

bool CDgnUnicodeTextWidth::IsDoubleSpaceText(const CString& csText)
{
	long nChar = csText.GetAt(0);
	if ( IsExistInSingleText(nChar) ) return false;
	if ( IsExistInDoubleText(nChar) ) return true;

	if ( nChar < 256 ) return false;
	if ( ( nChar >= 0x03B1 ) && ( nChar <= 0x03C9 ) ) return false; //¥á¥â¥ã¥ä¥å¥æ¥ç¥è¥é¥ê¥ë¥ì¥í¥î¥ï¥ð¥ñ¥ò¥ó¥ô¥õ¥ö¥÷¥ø
	if ( ( nChar >= 0xff61 ) && ( nChar <= 0xff9f ) ) return false;
	return true;
}

bool CDgnUnicodeTextWidth::IsFullWidthText(const CString& csText)
{
	long nData = m_mData.GetCount();
	if ( nData < 1 ) { ASSERT(0); return false; }

	auto L_IsFullWidthProperty = [ ] (const CString& csProp) -> bool
	{
		if ( csProp.CompareNoCase(_T("F")) == 0 ) return true; // East Asian Full Width
		if ( csProp.CompareNoCase(_T("H")) == 0 ) return false; // East Asian Half Width
		if ( csProp.CompareNoCase(_T("W")) == 0 ) return true; // East Asian Wide
		if ( csProp.CompareNoCase(_T("Na")) == 0 ) return false; // East Asian Narrow
		//if (csProp.CompareNoCase(_T("A" )) == 0) return false; // East Asian Ambiguous
		ASSERT(0); return false;
	};

	long nChar = csText.GetAt(0);

	D_UNICODE_TEXT_WIDTH* pData = nullptr;
	for ( long i = 0; i < nData; ++i )
	{
		if ( !m_mData.LookupEx(i, &pData) ) { ASSERT(0); continue; }

		if ( ( nChar >= pData->nFrom ) && ( nChar <= pData->nTo ) )
		{
			return L_IsFullWidthProperty(pData->csProp);
		}
	}

	ASSERT(0); return false;
}

void CDgnUnicodeTextWidth::BuildDataMap()
{
	CStringArray aData;
	GetDataString(aData);
	long nData = aData.GetCount();
	if ( nData < 1 ) { ASSERT(0); return; }

	m_mData.InitHashTable(nData);
	for ( long i = 0; i < nData; ++i )
	{
		D_UNICODE_TEXT_WIDTH TextWidth;
		if ( !GetMapData(TextWidth, aData[i]) ) { ASSERT(0); continue; }
		m_mData.SetAt(i, TextWidth);
	}
}

bool CDgnUnicodeTextWidth::GetMapData(D_UNICODE_TEXT_WIDTH& rTextWidth, CString& csText)
{
	int nPosColon = csText.Find(_T(";"));
	if ( nPosColon < 0 ) { ASSERT(0); return false; }

	CString csValue = csText.Left(nPosColon);
	if ( !GetDataValue(rTextWidth, csValue) ) { ASSERT(0); return false; }

	CString csInfo = csText.Mid(nPosColon + 1);
	if ( !GetDataInfo(rTextWidth, csInfo) ) { ASSERT(0); return false; }

	return true;
}

bool CDgnUnicodeTextWidth::GetDataValue(D_UNICODE_TEXT_WIDTH& rTextWidth, CString& csText)
{
	int nPosDotDot = csText.Find(_T(".."));
	if ( nPosDotDot > -1 )
	{
		CString csFrom = csText.Left(nPosDotDot);
		CString csTo = csText.Mid(nPosDotDot + 2);

		rTextWidth.nFrom = ConvertStringToInt(csFrom);
		rTextWidth.nTo   = ConvertStringToInt(csTo);
	}
	else
	{
		rTextWidth.nFrom = ConvertStringToInt(csText);
		rTextWidth.nTo   = rTextWidth.nFrom;
	}

	return ( ( rTextWidth.nFrom >= 0 ) && ( rTextWidth.nTo >= 0 ) ) ? true : false;
}

bool CDgnUnicodeTextWidth::GetDataInfo(D_UNICODE_TEXT_WIDTH& rTextWidth, CString& csText)
{
	int nPosBlank = csText.Find(_T(" "));
	if ( nPosBlank < 0 ) { ASSERT(0); return false; }

	rTextWidth.csProp = csText.Left(nPosBlank).Trim();
	rTextWidth.csDesc = csText.Mid(nPosBlank + 1).Trim();

	return rTextWidth.csProp.IsEmpty() ? false : true;
}

long CDgnUnicodeTextWidth::ConvertStringToInt(const CString& csStr)
{
	return strtol(( CStringA ) ( csStr ), nullptr, 16);
}

long CDgnUnicodeTextWidth::GetStringInt(const CString& csStr)
{
	return ( long ) ( csStr.GetAt(0) );
}

bool CDgnUnicodeTextWidth::IsExistInSingleText(long nChar)
{
	long nData = m_aSingleText.GetCount();
	for ( long i = 0; i < nData; ++i )
	{
		if ( nChar == m_aSingleText[i] )
		{
			return true;
		}
	}
	return false;
}

bool CDgnUnicodeTextWidth::IsExistInDoubleText(long nChar)
{
	long nData = m_aDoubleText.GetCount();
	for ( long i = 0; i < nData; ++i )
	{
		if ( nChar == m_aDoubleText[i] )
		{
			return true;
		}
	}
	return false;
}

